with open(KETU_JS, 'r', encoding='utf-8') as f:
    content = f.read()

signs_match = re.search(r'signs:\s*\{', content)
if signs_match:
    insertion_point = signs_match.end()
    leo_json = "\n    Leo: " + json.dumps(leo_data, indent=8) + ","
    new_content = content[:insertion_point] + leo_json + content[insertion_point:]
    
